import{_ as r,o as a,c as o,a2 as i}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"CONTRIBUER","description":"Deux voies pour contribuer : proposer un nouveau terme au glossaire officiel Cardano, ou améliorer / compléter le Glossaire Cardano en français.","frontmatter":{"description":"Deux voies pour contribuer : proposer un nouveau terme au glossaire officiel Cardano, ou améliorer / compléter le Glossaire Cardano en français.","pageClass":"contribuer"},"headers":[],"relativePath":"contribuer.md","filePath":"contribuer.md"}'),s={name:"contribuer.md"};function n(t,e,l,u,c,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="contribuer" tabindex="-1">CONTRIBUER <a class="header-anchor" href="#contribuer" aria-label="Permalink to &quot;CONTRIBUER&quot;">​</a></h1><p>Vous souhaitez rendre les concepts de Cardano plus accessibles ? Deux voies distinctes existent selon votre objectif. Choisissez celle qui correspond à votre contribution.</p><h2 id="_1-proposer-l-ajout-d-un-nouveau-terme-au-glossaire-officiel" tabindex="-1">1. Proposer l’ajout d’un nouveau terme au glossaire officiel <a class="header-anchor" href="#_1-proposer-l-ajout-d-un-nouveau-terme-au-glossaire-officiel" aria-label="Permalink to &quot;1. Proposer l’ajout d’un nouveau terme au glossaire officiel&quot;">​</a></h2><p>Si vous voulez <strong>faire ajouter un terme qui n’existe pas encore</strong> dans le glossaire officiel de Cardano (cardano.org), utilisez le dépôt officiel de la Cardano Foundation. C’est la voie à suivre pour enrichir la source de référence en anglais.</p><p>→ <a href="https://github.com/cardano-foundation/cardano-org/issues/new?labels=glossary&amp;title=Suggest+glossary+term%3A+" target="_blank" rel="noreferrer">Suggérer un terme au glossaire officiel (issue GitHub)</a></p><p>Indiquez clairement le terme proposé, une définition courte et, si possible, une source fiable. L’équipe du glossaire officiel examinera la demande.</p><h2 id="_2-ameliorer-ou-completer-le-glossaire-cardano-en-francais" tabindex="-1">2. Améliorer ou compléter le Glossaire Cardano en français <a class="header-anchor" href="#_2-ameliorer-ou-completer-le-glossaire-cardano-en-francais" aria-label="Permalink to &quot;2. Améliorer ou compléter le Glossaire Cardano en français&quot;">​</a></h2><p>Utilisez notre formulaire dans ces deux cas précis :</p><ol><li><strong>Améliorer le glossaire français</strong> : corriger une traduction, clarifier une définition, signaler une erreur, une formulation confuse ou un lien cassé sur ce site.</li><li><strong>Ajouter en français un terme déjà présent dans le glossaire officiel</strong> : vous avez remarqué un terme sur le <a href="https://cardano.org/glossary/" target="_blank" rel="noreferrer">glossaire officiel</a> qui n’est pas encore traduit ici, et vous souhaitez le faire figurer dans le Glossaire Cardano en français.</li></ol><p>→ <a href="https://docs.google.com/forms/d/e/1FAIpQLSflEjY5gmgpvWxq1W4MRuUb2DViZXgOSFoTfNhMoTBojChgKA/viewform?usp=publish-editor" target="_blank" rel="noreferrer">Formulaire : améliorer le glossaire français ou proposer un terme officiel à traduire</a></p><p>Précisez dans le formulaire s’il s’agit d’une amélioration d’une entrée existante ou de la traduction d’un terme déjà listé sur cardano.org. Ajoutez si possible le lien vers l’entrée officielle et une source de vérification.</p><h2 id="bonnes-pratiques" tabindex="-1">Bonnes pratiques <a class="header-anchor" href="#bonnes-pratiques" aria-label="Permalink to &quot;Bonnes pratiques&quot;">​</a></h2><ul><li>Incluez une source fiable pour chaque proposition.</li><li>Les contributions au glossaire français sont examinées avant publication, afin de garder clarté, cohérence et fiabilité.</li><li>Ce glossaire français est une initiative communautaire indépendante : il ne remplace pas les documents officiels.</li></ul><p>Merci de contribuer à l’accès aux connaissances Cardano en français.</p>',14)])])}const m=r(s,[["render",n]]);export{p as __pageData,m as default};
